pub enum StateDurabilityEvidenceVerdict<Target: Clone, ReadbackSubject: Clone> {
    StateDurabilityEvidenceAccepted {
        evidence: Rc<Vec<Rc<StateDurabilityEvidence<Target, ReadbackSubject>>>>,
    },
    StateDurabilityEvidenceRefused {
        cause: Rc<StateDurabilityRefusal<Target, ReadbackSubject>>,
    },
}

impl<Target: Clone + std::fmt::Debug, ReadbackSubject: Clone + std::fmt::Debug> std::fmt::Debug for StateDurabilityEvidenceVerdict<Target, ReadbackSubject> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::StateDurabilityEvidenceAccepted { evidence } => f.debug_struct("StateDurabilityEvidenceAccepted").field("evidence", evidence).finish(),
            Self::StateDurabilityEvidenceRefused { cause } => f.debug_struct("StateDurabilityEvidenceRefused").field("cause", cause).finish(),
        }
    }
}

impl<Target: Clone + PartialEq, ReadbackSubject: Clone + PartialEq> PartialEq for StateDurabilityEvidenceVerdict<Target, ReadbackSubject> {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Self::StateDurabilityEvidenceAccepted { evidence: a_evidence }, Self::StateDurabilityEvidenceAccepted { evidence: b_evidence }) => a_evidence == b_evidence,
            (Self::StateDurabilityEvidenceRefused { cause: a_cause }, Self::StateDurabilityEvidenceRefused { cause: b_cause }) => a_cause == b_cause,
            _ => false,
        }
    }
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct StateDurabilityBoundaryUniquenessFold {
    pub seen: Rc<Vec<Rc<StateDurabilityBoundary>>>,
    pub duplicate: Option<Rc<StateDurabilityBoundary>>,
    pub duplicate_count: i64,
}

pub fn state_durability_boundary_requirements_refusal<Target: Clone, ReadbackSubject: Clone>(requirements: Rc<StateDurabilityBoundaryRequirements>) -> Option<Rc<StateDurabilityRefusal<Target, ReadbackSubject>>> {
    {
        let boundaries = state_durability_boundary_requirement_list(requirements);
let folded = boundaries.iter().cloned().fold(Rc::new(StateDurabilityBoundaryUniquenessFold {
    seen: Rc::new(vec![]),
    duplicate: std::option::Option::None,
    duplicate_count: 0,
}), |acc: Rc<StateDurabilityBoundaryUniquenessFold>, boundary: Rc<StateDurabilityBoundary>| match acc.duplicate.clone() {
    Some(duplicate) => if (boundary.clone() == duplicate.clone()) {
            Rc::new(StateDurabilityBoundaryUniquenessFold {
    seen: acc.seen.clone(),
    duplicate: acc.duplicate.clone(),
    duplicate_count: v1_rt::int_add(acc.duplicate_count.clone(), 1),
})
        } else {
            acc.clone()
        },
    std::option::Option::None => if { let mut __found = false; for existing in acc.seen.clone().iter().cloned() { if (existing.clone() == boundary.clone()) { __found = true; break; } } __found } {
            Rc::new(StateDurabilityBoundaryUniquenessFold {
    seen: acc.seen.clone(),
    duplicate: Some(boundary.clone()),
    duplicate_count: 2,
})
        } else {
            Rc::new(StateDurabilityBoundaryUniquenessFold {
    seen: v1_rt::rc_list_concat(acc.seen.clone(), Rc::new(vec![boundary.clone()])),
    duplicate: std::option::Option::None,
    duplicate_count: 0,
})
        },
});
match folded.duplicate.clone() {
    Some(boundary) => Some(Rc::new(StateDurabilityRefusal::DurabilityRequirementDuplicate {
    boundary: boundary.clone(),
    count: folded.duplicate_count.clone(),
})),
    std::option::Option::None => std::option::Option::None,
}
}
}

pub fn state_durability_admission_eq<Target: Clone + PartialEq, ReadbackSubject: Clone + PartialEq>(a: Rc<StateDurabilityAdmission<Target, ReadbackSubject>>, b: Rc<StateDurabilityAdmission<Target, ReadbackSubject>>) -> bool {
    ((((((a.target.clone() == b.target.clone()) && (a.desired_state_digest.clone() == b.desired_state_digest.clone())) && (a.realization.clone() == b.realization.clone())) && (a.capability_version.clone() == b.capability_version.clone())) && (a.perturbation_generation.clone() == b.perturbation_generation.clone())) && (a.readback_subject.clone() == b.readback_subject.clone()))
}

pub fn state_durability_capability_matches_admission<Target: Clone, ReadbackSubject: Clone>(capability: Rc<StateDurabilityCapability>, admission: Rc<StateDurabilityAdmission<Target, ReadbackSubject>>) -> bool {
    ((capability.realization.clone() == admission.realization.clone()) && (capability.capability_version.clone() == admission.capability_version.clone()))
}

pub fn state_durability_evidence_cardinality<Target: Clone + PartialEq, ReadbackSubject: Clone + PartialEq>(evidence: Rc<Vec<Rc<StateDurabilityEvidence<Target, ReadbackSubject>>>>, admission: Rc<StateDurabilityAdmission<Target, ReadbackSubject>>, boundary: Rc<StateDurabilityBoundary>) -> Rc<StateDurabilityEvidenceCardinality<Target, ReadbackSubject>> {
    evidence.iter().cloned().fold(Rc::new(StateDurabilityEvidenceCardinality::NoMatchingDurabilityEvidence), |cardinality: Rc<StateDurabilityEvidenceCardinality<Target, ReadbackSubject>>, candidate: Rc<StateDurabilityEvidence<Target, ReadbackSubject>>| if (state_durability_admission_eq(candidate.admission.clone(), admission.clone()) && (candidate.perturbation.boundary.clone() == boundary.clone())) {
        match (*cardinality).clone() {
    StateDurabilityEvidenceCardinality::NoMatchingDurabilityEvidence => Rc::new(StateDurabilityEvidenceCardinality::OneMatchingDurabilityEvidence {
    evidence: candidate.clone(),
}),
    StateDurabilityEvidenceCardinality::OneMatchingDurabilityEvidence { evidence: _, .. } => Rc::new(StateDurabilityEvidenceCardinality::MultipleMatchingDurabilityEvidence {
    count: 2,
}),
    StateDurabilityEvidenceCardinality::MultipleMatchingDurabilityEvidence { count: count, .. } => Rc::new(StateDurabilityEvidenceCardinality::MultipleMatchingDurabilityEvidence {
    count: v1_rt::int_add(count.clone(), 1),
}),
}
    } else {
        cardinality
    })
}

pub fn state_durability_admission_evidence_cardinality<Target: Clone + PartialEq, ReadbackSubject: Clone + PartialEq>(evidence: Rc<Vec<Rc<StateDurabilityEvidence<Target, ReadbackSubject>>>>, admission: Rc<StateDurabilityAdmission<Target, ReadbackSubject>>) -> Rc<StateDurabilityEvidenceCardinality<Target, ReadbackSubject>> {
    evidence.iter().cloned().fold(Rc::new(StateDurabilityEvidenceCardinality::NoMatchingDurabilityEvidence), |cardinality: Rc<StateDurabilityEvidenceCardinality<Target, ReadbackSubject>>, candidate: Rc<StateDurabilityEvidence<Target, ReadbackSubject>>| if state_durability_admission_eq(candidate.admission.clone(), admission.clone()) {
        match (*cardinality).clone() {
    StateDurabilityEvidenceCardinality::NoMatchingDurabilityEvidence => Rc::new(StateDurabilityEvidenceCardinality::OneMatchingDurabilityEvidence {
    evidence: candidate.clone(),
}),
    StateDurabilityEvidenceCardinality::OneMatchingDurabilityEvidence { evidence: _, .. } => Rc::new(StateDurabilityEvidenceCardinality::MultipleMatchingDurabilityEvidence {
    count: 2,
}),
    StateDurabilityEvidenceCardinality::MultipleMatchingDurabilityEvidence { count: count, .. } => Rc::new(StateDurabilityEvidenceCardinality::MultipleMatchingDurabilityEvidence {
    count: v1_rt::int_add(count.clone(), 1),
}),
}
    } else {
        cardinality
    })
}

pub fn state_durability_evidence_refusal<Target: Clone + PartialEq, ReadbackSubject: Clone + PartialEq>(admission: Rc<StateDurabilityAdmission<Target, ReadbackSubject>>, boundary: Rc<StateDurabilityBoundary>, evidence: Rc<StateDurabilityEvidence<Target, ReadbackSubject>>) -> Option<Rc<StateDurabilityRefusal<Target, ReadbackSubject>>> {
    if (evidence.perturbation.target.clone() != admission.target.clone()) {
        Some(Rc::new(StateDurabilityRefusal::DurabilityPerturbationTargetMismatch {
    expected: admission.target.clone(),
    observed: evidence.perturbation.target.clone(),
}))
    } else {
        if (evidence.perturbation.boundary.clone() != boundary.clone()) {
            Some(Rc::new(StateDurabilityRefusal::DurabilityPerturbationBoundaryMismatch {
    expected: boundary.clone(),
    observed: evidence.perturbation.boundary.clone(),
}))
        } else {
            if (evidence.perturbation.generation.clone() != admission.perturbation_generation.clone()) {
                Some(Rc::new(StateDurabilityRefusal::DurabilityPerturbationGenerationMismatch {
    expected: admission.perturbation_generation.clone(),
    observed: evidence.perturbation.generation.clone(),
}))
            } else {
                match (*evidence.outcome.clone()).clone() {
    StatePreservationOutcome::StatePreservationObservationRefused { reason: reason, .. } => Some(Rc::new(StateDurabilityRefusal::DurabilityObservationRefused {
    reason: reason.clone(),
})),
    StatePreservationOutcome::StateLost { before, after, reason, .. } => Some(Rc::new(StateDurabilityRefusal::DurabilityStateLost {
    before: before.clone(),
    after: after.clone(),
    reason: reason.clone(),
})),
    StatePreservationOutcome::StatePreserved { before, after, activation, .. } => if (before.perturbation_receipt_id.clone() != evidence.perturbation.receipt_id.clone()) {
                    Some(Rc::new(StateDurabilityRefusal::DurabilityReadbackReceiptLinkMismatch {
    position: StateReadbackPosition::BeforeBoundaryReadback,
    expected_receipt_id: evidence.perturbation.receipt_id.clone(),
    observed_receipt_id: before.perturbation_receipt_id.clone(),
}))
                } else {
                    if (after.perturbation_receipt_id.clone() != evidence.perturbation.receipt_id.clone()) {
                        Some(Rc::new(StateDurabilityRefusal::DurabilityReadbackReceiptLinkMismatch {
    position: StateReadbackPosition::AfterBoundaryReadback,
    expected_receipt_id: evidence.perturbation.receipt_id.clone(),
    observed_receipt_id: after.perturbation_receipt_id.clone(),
}))
                    } else {
                        if (before.target.clone() != admission.target.clone()) {
                            Some(Rc::new(StateDurabilityRefusal::DurabilityReadbackTargetMismatch {
    position: StateReadbackPosition::BeforeBoundaryReadback,
    expected: admission.target.clone(),
    observed: before.target.clone(),
}))
                        } else {
                            if (after.target.clone() != admission.target.clone()) {
                                Some(Rc::new(StateDurabilityRefusal::DurabilityReadbackTargetMismatch {
    position: StateReadbackPosition::AfterBoundaryReadback,
    expected: admission.target.clone(),
    observed: after.target.clone(),
}))
                            } else {
                                if (before.subject.clone() != admission.readback_subject.clone()) {
                                    Some(Rc::new(StateDurabilityRefusal::DurabilityReadbackSubjectMismatch {
    position: StateReadbackPosition::BeforeBoundaryReadback,
    expected: admission.readback_subject.clone(),
    observed: before.subject.clone(),
}))
                                } else {
                                    if (after.subject.clone() != admission.readback_subject.clone()) {
                                        Some(Rc::new(StateDurabilityRefusal::DurabilityReadbackSubjectMismatch {
    position: StateReadbackPosition::AfterBoundaryReadback,
    expected: admission.readback_subject.clone(),
    observed: after.subject.clone(),
}))
                                    } else {
                                        if ((before.state_digest.clone() != admission.desired_state_digest.clone()) || (after.state_digest.clone() != admission.desired_state_digest.clone())) {
                                            Some(Rc::new(StateDurabilityRefusal::DurabilityDesiredStateMismatch {
    desired: admission.desired_state_digest.clone(),
    before: before.state_digest.clone(),
    after: after.state_digest.clone(),
}))
                                        } else {
                                            match (*activation.clone()).clone() {
    StateActivationEvidence::ActivationUnverified { reason: reason, .. } => Some(Rc::new(StateDurabilityRefusal::DurabilityActivationUnverified {
    reason: reason.clone(),
})),
    StateActivationEvidence::ActivationVerified { receipt: receipt, .. } => if (receipt.perturbation_receipt_id.clone() != evidence.perturbation.receipt_id.clone()) {
                                                Some(Rc::new(StateDurabilityRefusal::DurabilityActivationReceiptLinkMismatch {
    expected_receipt_id: evidence.perturbation.receipt_id.clone(),
    observed_receipt_id: receipt.perturbation_receipt_id.clone(),
}))
                                            } else {
                                                if ((((((receipt.target.clone() != admission.target.clone()) || (receipt.subject.clone() != admission.readback_subject.clone())) || (receipt.desired_state_digest.clone() != admission.desired_state_digest.clone())) || (receipt.realization.clone() != admission.realization.clone())) || (receipt.capability_version.clone() != admission.capability_version.clone())) || (receipt.perturbation_generation.clone() != admission.perturbation_generation.clone())) {
                                                    Some(Rc::new(StateDurabilityRefusal::DurabilityActivationScopeMismatch {
    expected: admission.clone(),
    observed: receipt.clone(),
}))
                                                } else {
                                                    std::option::Option::None
                                                }
                                            },
}
                                        }
                                    }
                                }
                            }
                        }
                    }
                },
}
            }
        }
    }
}

pub fn state_durability_boundary_evidence_verdict<Target: Clone + PartialEq, ReadbackSubject: Clone + PartialEq>(boundary: Rc<StateDurabilityBoundary>, admission: Rc<StateDurabilityAdmission<Target, ReadbackSubject>>, capability: Rc<StateDurabilityCapability>, evidence: Rc<Vec<Rc<StateDurabilityEvidence<Target, ReadbackSubject>>>>) -> Rc<StateDurabilityEvidenceVerdict<Target, ReadbackSubject>> {
    if !{ let mut __found = false; for supported in capability.supported_boundaries.clone().iter().cloned() { if (supported.clone() == boundary.clone()) { __found = true; break; } } __found } {
        Rc::new(StateDurabilityEvidenceVerdict::StateDurabilityEvidenceRefused {
    cause: Rc::new(StateDurabilityRefusal::DurabilityBoundaryUnsupported {
    realization: capability.realization.clone(),
    boundary: boundary.clone(),
}),
})
    } else {
        match (*state_durability_evidence_cardinality(evidence.clone(), admission.clone(), boundary.clone())).clone() {
    StateDurabilityEvidenceCardinality::NoMatchingDurabilityEvidence => match (*state_durability_admission_evidence_cardinality(evidence.clone(), admission.clone())).clone() {
    StateDurabilityEvidenceCardinality::OneMatchingDurabilityEvidence { evidence: mismatched, .. } => match state_durability_evidence_refusal(admission.clone(), boundary.clone(), mismatched.clone()) {
    Some(cause) => Rc::new(StateDurabilityEvidenceVerdict::StateDurabilityEvidenceRefused {
    cause: cause.clone(),
}),
    std::option::Option::None => Rc::new(StateDurabilityEvidenceVerdict::StateDurabilityEvidenceRefused {
    cause: Rc::new(StateDurabilityRefusal::DurabilityEvidenceMissing {
    admission: admission.clone(),
    boundary: boundary.clone(),
}),
}),
},
    StateDurabilityEvidenceCardinality::NoMatchingDurabilityEvidence => Rc::new(StateDurabilityEvidenceVerdict::StateDurabilityEvidenceRefused {
    cause: Rc::new(StateDurabilityRefusal::DurabilityEvidenceMissing {
    admission: admission.clone(),
    boundary: boundary.clone(),
}),
}),
    StateDurabilityEvidenceCardinality::MultipleMatchingDurabilityEvidence { count: _, .. } => Rc::new(StateDurabilityEvidenceVerdict::StateDurabilityEvidenceRefused {
    cause: Rc::new(StateDurabilityRefusal::DurabilityEvidenceMissing {
    admission: admission.clone(),
    boundary: boundary.clone(),
}),
}),
},
    StateDurabilityEvidenceCardinality::MultipleMatchingDurabilityEvidence { count: count, .. } => Rc::new(StateDurabilityEvidenceVerdict::StateDurabilityEvidenceRefused {
    cause: Rc::new(StateDurabilityRefusal::DurabilityEvidenceAmbiguous {
    admission: admission.clone(),
    boundary: boundary.clone(),
    count: count.clone(),
}),
}),
    StateDurabilityEvidenceCardinality::OneMatchingDurabilityEvidence { evidence: receipt, .. } => match state_durability_evidence_refusal(admission.clone(), boundary.clone(), receipt.clone()) {
    Some(cause) => Rc::new(StateDurabilityEvidenceVerdict::StateDurabilityEvidenceRefused {
    cause: cause.clone(),
}),
    std::option::Option::None => Rc::new(StateDurabilityEvidenceVerdict::StateDurabilityEvidenceAccepted {
    evidence: Rc::new(vec![receipt.clone()]),
}),
},
}
    }
}

#[derive(Clone, serde::Serialize, serde::Deserialize)]
#[serde(bound(serialize = "Target: Clone + serde::Serialize, ReadbackSubject: Clone + serde::Serialize", deserialize = "Target: Clone + serde::Deserialize<'de>, ReadbackSubject: Clone + serde::Deserialize<'de>"))]
pub struct StateDurabilityEvidenceFold<Target: Clone, ReadbackSubject: Clone> {
    pub refusal: Option<Rc<StateDurabilityRefusal<Target, ReadbackSubject>>>,
    pub accepted: Rc<Vec<Rc<StateDurabilityEvidence<Target, ReadbackSubject>>>>,
    pub _phantom: std::marker::PhantomData<(Target, ReadbackSubject)>,
}

impl<Target: Clone + std::fmt::Debug, ReadbackSubject: Clone + std::fmt::Debug> std::fmt::Debug for StateDurabilityEvidenceFold<Target, ReadbackSubject> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("StateDurabilityEvidenceFold").field("refusal", &self.refusal).field("accepted", &self.accepted).finish()
    }
}

impl<Target: Clone + PartialEq, ReadbackSubject: Clone + PartialEq> PartialEq for StateDurabilityEvidenceFold<Target, ReadbackSubject> {
    fn eq(&self, other: &Self) -> bool {
        self.refusal == other.refusal && self.accepted == other.accepted
    }
}

pub fn state_durability_boundaries_evidence_verdict<Target: Clone + PartialEq, ReadbackSubject: Clone + PartialEq>(required: Rc<StateDurabilityBoundaryRequirements>, admission: Rc<StateDurabilityAdmission<Target, ReadbackSubject>>, capability: Rc<StateDurabilityCapability>, evidence: Rc<Vec<Rc<StateDurabilityEvidence<Target, ReadbackSubject>>>>) -> Rc<StateDurabilityEvidenceVerdict<Target, ReadbackSubject>> {
    {
        let required_list = state_durability_boundary_requirement_list(required);
let folded = required_list.iter().cloned().fold(Rc::new(StateDurabilityEvidenceFold {
    refusal: std::option::Option::None,
    accepted: Rc::new(vec![]),
    _phantom: std::marker::PhantomData,
}), |acc: Rc<StateDurabilityEvidenceFold<Target, ReadbackSubject>>, boundary: Rc<StateDurabilityBoundary>| match acc.refusal.clone() {
    Some(_) => acc.clone(),
    std::option::Option::None => match (*state_durability_boundary_evidence_verdict(boundary.clone(), admission.clone(), capability.clone(), evidence.clone())).clone() {
    StateDurabilityEvidenceVerdict::StateDurabilityEvidenceRefused { cause: cause, .. } => Rc::new(StateDurabilityEvidenceFold {
    refusal: Some(cause.clone()),
    accepted: acc.accepted.clone(),
    _phantom: std::marker::PhantomData,
}),
    StateDurabilityEvidenceVerdict::StateDurabilityEvidenceAccepted { evidence: matched, .. } => Rc::new(StateDurabilityEvidenceFold {
    refusal: std::option::Option::None,
    accepted: v1_rt::rc_list_concat(acc.accepted.clone(), matched.clone()),
    _phantom: std::marker::PhantomData,
}),
},
});
match folded.refusal.clone() {
    Some(cause) => Rc::new(StateDurabilityEvidenceVerdict::StateDurabilityEvidenceRefused {
    cause: cause.clone(),
}),
    std::option::Option::None => Rc::new(StateDurabilityEvidenceVerdict::StateDurabilityEvidenceAccepted {
    evidence: folded.accepted.clone(),
}),
}
}
}

pub fn state_durability_verdict<Target: Clone + PartialEq, ReadbackSubject: Clone + PartialEq>(intent: Rc<StateDurabilityIntent>, admission: Rc<StateDurabilityAdmission<Target, ReadbackSubject>>, capability: Option<Rc<StateDurabilityCapability>>, evidence: Rc<Vec<Rc<StateDurabilityEvidence<Target, ReadbackSubject>>>>) -> Rc<StateDurabilityVerdict<Target, ReadbackSubject>> {
    match (*intent.clone()).clone() {
    StateDurabilityIntent::DurabilityUnspecified => Rc::new(StateDurabilityVerdict::StateDurabilityRefused {
    cause: Rc::new(StateDurabilityRefusal::DurabilityIntentUnspecified),
}),
    StateDurabilityIntent::RuntimeLifetimeOnly => Rc::new(StateDurabilityVerdict::StateDurabilityQualified {
    qualification: Rc::new(StateDurabilityQualification::RuntimeLifetimeQualification {
    admission: admission.clone(),
}),
}),
    StateDurabilityIntent::DurableAcross { boundaries: boundaries, .. } => match state_durability_boundary_requirements_refusal(boundaries.clone()) {
    Some(cause) => Rc::new(StateDurabilityVerdict::StateDurabilityRefused {
    cause: cause.clone(),
}),
    std::option::Option::None => match capability.clone() {
    std::option::Option::None => Rc::new(StateDurabilityVerdict::StateDurabilityRefused {
    cause: Rc::new(StateDurabilityRefusal::DurabilityCapabilityMissing),
}),
    Some(realizer) => if !state_durability_capability_matches_admission(realizer.clone(), admission.clone()) {
        Rc::new(StateDurabilityVerdict::StateDurabilityRefused {
    cause: Rc::new(StateDurabilityRefusal::DurabilityCapabilityAdmissionMismatch {
    expected_realization: admission.realization.clone(),
    observed_realization: realizer.realization.clone(),
    expected_capability_version: admission.capability_version.clone(),
    observed_capability_version: realizer.capability_version.clone(),
}),
})
    } else {
        match realizer.commit_barrier.clone() {
    DurabilityCommitBarrier::NoDurabilityCommitBarrier => Rc::new(StateDurabilityVerdict::StateDurabilityRefused {
    cause: Rc::new(StateDurabilityRefusal::DurabilityCommitBarrierMissing {
    realization: realizer.realization.clone(),
}),
}),
    DurabilityCommitBarrier::SynchronizedCommit => match state_durability_definition_linkage_refusal(admission.clone()) {
    Some(cause) => Rc::new(StateDurabilityVerdict::StateDurabilityRefused {
    cause: cause.clone(),
}),
    std::option::Option::None => match (*state_durability_boundaries_evidence_verdict(boundaries.clone(), admission.clone(), realizer.clone(), evidence)).clone() {
    StateDurabilityEvidenceVerdict::StateDurabilityEvidenceRefused { cause: cause, .. } => Rc::new(StateDurabilityVerdict::StateDurabilityRefused {
    cause: cause.clone(),
}),
    StateDurabilityEvidenceVerdict::StateDurabilityEvidenceAccepted { evidence: accepted, .. } => Rc::new(StateDurabilityVerdict::StateDurabilityQualified {
    qualification: Rc::new(StateDurabilityQualification::DurableLifetimeQualification {
    admission: admission.clone(),
    capability: realizer.clone(),
    boundaries: boundaries.clone(),
    evidence: accepted.clone(),
}),
}),
},
},
}
    },
},
},
}
}

